INSERT INTO movies (title, description, release_year, duration, has_oscar, poster_url, trailer_url, netflix_url, content_type, seasons, total_episodes, episodes_per_season) VALUES
('The Godfather', 'The aging patriarch of an organized crime dynasty, Don Vito Corleone, transfers control of his clandestine empire to his reluctant youngest son, Michael. Spanning a decade of family history, the film chronicles Michael''s transformation from a decorated war hero who wants nothing to do with the family business into a ruthless mafia boss — a tragic metamorphosis that costs him his soul and everyone he loves.', 1972, 175, true, 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', 'https://www.youtube.com/watch?v=sY1S34973zA', 'https://www.netflix.com/title/60011152', 'movie', NULL, NULL, NULL),
('The Dark Knight', 'When the maniacal Joker emerges as a new force of chaos in Gotham City, Batman must confront the greatest psychological and physical test of his ability to fight injustice. As the Joker''s anarchic mastermind pushes Gotham into escalating madness -- targeting the city''s souls as much as its structures -- the Dark Knight must accept one of the greatest sacrifices to save everyone he cares about, blurring the line between hero and vigilante.', 2008, 152, false, 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', 'https://www.youtube.com/watch?v=EXeTwQWrcwY', 'https://www.netflix.com/title/70079583', 'movie', NULL, NULL, NULL),
('Parasite', 'The impoverished Kim family schemes their way into employment by the wealthy Park family, infiltrating their luxurious home one member at a time through an elaborate web of deception. As the two families become inextricably intertwined, a series of unexpected events expose the violent fault lines of class inequality in modern South Korea, building to a shocking and unforgettable climax that shatters both families'' carefully constructed worlds.', 2019, 132, true, 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', 'https://www.youtube.com/watch?v=5xH0HfJHsaY', 'https://www.netflix.com/title/81227040', 'movie', NULL, NULL, NULL),
('Gladiator', 'Maximus Decimus Meridius, Rome''s most trusted general, is betrayed by the corrupt Emperor Commodus, who murders Maximus''s family and condemns him to slavery. Rising through the ranks of the brutal gladiatorial arena, Maximus captures the hearts of Rome''s citizens as he fights his way back to power with a single, burning purpose: to avenge his family and restore the Roman Republic that his beloved Emperor Marcus Aurelius envisioned.', 2000, 155, true, 'https://image.tmdb.org/t/p/w500/ty8TGRuvJLPUmAR1H1nRIsgwvim.jpg', 'https://www.youtube.com/watch?v=owK1qxDselE', 'https://www.netflix.com/title/26736291', 'movie', NULL, NULL, NULL),
('Inception', 'Dom Cobb is the world''s most skilled practitioner of extraction — the art of stealing secrets from deep within the subconscious during the dream state. Offered a chance to have his criminal record erased and return to his children, Cobb must accomplish the impossible: inception, planting an idea into a target''s mind. He assembles a team of specialists for a dangerous multi-layered journey through dreams within dreams, where the boundaries between reality and illusion dissolve.', 2010, 148, false, 'https://image.tmdb.org/t/p/w500/9gk7adHYeDvHkCSEqAvQNLV5Uge.jpg', 'https://www.youtube.com/watch?v=YoHD9XEInc0', 'https://www.netflix.com/title/70131314', 'movie', NULL, NULL, NULL),
('The Shawshank Redemption', 'Wrongfully convicted of murdering his wife and her lover, banker Andy Dufresne is sentenced to two consecutive life terms at Shawshank State Penitentiary. Over the course of two decades, Andy forms an unlikely friendship with fellow inmate Red and quietly transforms the prison through acts of decency and hope, all while harboring a secret plan that will come to fruition in the most extraordinary way. A testament to the resilience of the human spirit.', 1994, 142, false, 'https://image.tmdb.org/t/p/w500/q6y0Go1tsGEsmtFryDOJo3dEmqu.jpg', 'https://www.youtube.com/watch?v=6hB3S9d6lUo', 'https://www.netflix.com/title/70005379', 'movie', NULL, NULL, NULL),
('Breaking Bad', 'Walter White, an overqualified and underpaid high school chemistry teacher in Albuquerque, New Mexico, is diagnosed with terminal lung cancer on his 50th birthday. Desperate to secure his family''s financial future, Walt partners with his former student Jesse Pinkman to manufacture and sell crystal methamphetamine. What begins as a desperate act of paternal love becomes a terrifying descent into power, violence, and moral corruption that transforms a mild-mannered teacher into the feared drug lord known as Heisenberg.', 2008, 49, false, 'https://image.tmdb.org/t/p/w500/ggFHVNu6YYI5L9pCfOacjizRGt.jpg', 'https://www.youtube.com/watch?v=HhesaQXLuRY', 'https://www.netflix.com/title/70143836', 'series', 5, 62, '[{"season":1,"episodes":7},{"season":2,"episodes":13},{"season":3,"episodes":13},{"season":4,"episodes":13},{"season":5,"episodes":16}]'::jsonb),
('Game of Thrones', 'In the sprawling continents of Westeros and Essos, noble houses wage war for control of the Iron Throne while an ancient supernatural threat gathers strength beyond the massive Wall in the frozen North. From the scheming corridors of King''s Landing to the vast Dothraki plains and the icy wastes beyond the Wall, the fates of kings, queens, warriors, and outcasts intertwine in an epic saga of power, betrayal, love, and sacrifice where no character is safe and winter is always coming.', 2011, 57, false, 'https://image.tmdb.org/t/p/w500/1XS1oqL89opfnbLl8WnZY1O1uJx.jpg', 'https://www.youtube.com/watch?v=KPLWWIOCOOQ', 'https://www.netflix.com/title/70220052', 'series', 8, 73, '[{"season":1,"episodes":10},{"season":2,"episodes":10},{"season":3,"episodes":10},{"season":4,"episodes":10},{"season":5,"episodes":10},{"season":6,"episodes":10},{"season":7,"episodes":7},{"season":8,"episodes":6}]'::jsonb),
('Stranger Things', 'In the small town of Hawkins, Indiana, the mysterious disappearance of twelve-year-old Will Byers sets off a chain of events that uncovers secret government experiments, a terrifying alternate dimension called the Upside Down, and a telekinetic girl named Eleven who escaped from a nearby laboratory. As the town''s residents — led by the kids on their bicycles, a determined mother, and a cynical police chief — confront increasingly powerful interdimensional threats, they discover that the bonds of friendship and family are the most powerful weapons against the darkness.', 2016, 51, false, 'https://image.tmdb.org/t/p/w500/49WJfeN0moxb9IPfGn8AIqMGskD.jpg', 'https://www.youtube.com/watch?v=b9EkMc79ZSU', 'https://www.netflix.com/title/80057281', 'series', 4, 34, '[{"season":1,"episodes":8},{"season":2,"episodes":9},{"season":3,"episodes":8},{"season":4,"episodes":9}]'::jsonb),
('The Witcher', 'Geralt of Rivia, a mutated monster hunter known as a Witcher, struggles to find his place in a world where people often prove more wicked than the beasts he hunts. As war rages across the Continent, Geralt''s destiny becomes intertwined with those of Yennefer of Vengerberg, a powerful sorceress seeking purpose, and Princess Ciri of Cintra, a young woman fleeing destruction who holds the key to an ancient prophecy. Their paths converge in a tale of fate, magic, and the blurred lines between good and evil.', 2019, 60, false, 'https://image.tmdb.org/t/p/w500/7vjaCdMw15FEbXyLQTVa04URsPm.jpg', 'https://www.youtube.com/watch?v=ndl1W4ltcmg', 'https://www.netflix.com/title/80189685', 'series', 3, 24, '[{"season":1,"episodes":8},{"season":2,"episodes":8},{"season":3,"episodes":8}]'::jsonb),
('Money Heist', 'A mysterious mastermind known only as "The Professor" recruits eight criminals with nothing to lose, assigning them codenames of cities, to carry out an audacious heist on the Royal Mint of Spain. Locked inside with hostages for days, the crew must execute a meticulous plan to print billions of euros while evading an elite police negotiator and managing the volatile dynamics within the group. A thrilling cat-and-mouse game that captivated the world and redefined the heist genre.', 2017, 50, false, 'https://image.tmdb.org/t/p/w500/reEMJA1uzscCbkpeRJeTT2bjqUp.jpg', 'https://www.youtube.com/watch?v=p_PJbmrX4uk', 'https://www.netflix.com/title/80192098', 'series', 5, 41, '[{"season":1,"episodes":9},{"season":2,"episodes":6},{"season":3,"episodes":8},{"season":4,"episodes":8},{"season":5,"episodes":10}]'::jsonb),
('Dark', 'In the small German town of Winden, the disappearance of two young children exposes the fractured relationships, double lives, and dark pasts of four interconnected families. As residents investigate, they uncover an extraordinary time-travel conspiracy spanning multiple generations and parallel worlds, where events in the past, present, and future are inextricably linked. A mind-bending sci-fi masterpiece that weaves together quantum physics, determinism, and the cyclical nature of human suffering.', 2017, 52, false, 'https://image.tmdb.org/t/p/w500/apbrbWs8M9lyOpJYU5WXrpFbk1Z.jpg', 'https://www.youtube.com/watch?v=rrwycJ08PSA', 'https://www.netflix.com/title/80100172', 'series', 3, 26, '[{"season":1,"episodes":10},{"season":2,"episodes":8},{"season":3,"episodes":8}]'::jsonb),
('The Crown', 'Beginning with the wedding of Princess Elizabeth to Philip Mountbatten in 1947, The Crown chronicles the reign of Queen Elizabeth II across decades of political upheaval, personal crisis, and social transformation. From the Suez Crisis and the moon landing to the Falklands War and the rise of Margaret Thatcher, each season illuminates the impossible balancing act between the monarch''s duty to the nation and the desires of the woman behind the crown, set against the grandeur and constraint of royal life.', 2016, 58, false, 'https://image.tmdb.org/t/p/w500/1M876KPjulVwppEpldhdc8V4o68.jpg', 'https://www.youtube.com/watch?v=JWtnJjn6ng0', 'https://www.netflix.com/title/80025678', 'series', 6, 60, '[{"season":1,"episodes":10},{"season":2,"episodes":10},{"season":3,"episodes":10},{"season":4,"episodes":10},{"season":5,"episodes":10},{"season":6,"episodes":10}]'::jsonb),
('Peaky Blinders', 'In the lawless streets of 1919 Birmingham, England, the Shelby crime family — led by the ruthlessly ambitious Thomas Shelby, a traumatized World War I veteran — builds a criminal empire from their legitimate betting shop front, the Peaky Blinders. As Tommy navigates a treacherous landscape of rival gangs, corrupt politicians, and determined law enforcement, his ambitions grow from the grimy back alleys of Small Heath to the corridors of British political power, always at a devastating personal cost.', 2013, 55, false, 'https://image.tmdb.org/t/p/w500/vUUqzWa2LnHIVqkaKVlVGkVcZIW.jpg', 'https://www.youtube.com/watch?v=oVzVdvGIC7U', 'https://www.netflix.com/title/80002479', 'series', 6, 36, '[{"season":1,"episodes":6},{"season":2,"episodes":6},{"season":3,"episodes":6},{"season":4,"episodes":6},{"season":5,"episodes":6},{"season":6,"episodes":6}]'::jsonb),
('The Mandalorian', 'Five years after the fall of the Galactic Empire, a lone bounty hunter known only as the Mandalorian operates in the lawless outer reaches of the galaxy, far from the authority of the New Republic. When a high-value bounty turns out to be a mysterious alien child with extraordinary powers — known affectionately as "The Child" — the Mandalorian breaks from his guild and becomes the infant''s protector, embarking on a dangerous journey across the galaxy that will test his code, his combat skills, and his capacity for connection.', 2019, 40, false, 'https://image.tmdb.org/t/p/w500/eU1i6eHXlzMOlEq0ku1Bdo719Nm.jpg', 'https://www.youtube.com/watch?v=aOC8E8z_ifw', 'https://www.netflix.com/title/81230911', 'series', 3, 24, '[{"season":1,"episodes":8},{"season":2,"episodes":8},{"season":3,"episodes":8}]'::jsonb),
('Chernobyl', 'On April 26, 1986, the No. 4 reactor at the Chernobyl Nuclear Power Plant in Soviet Ukraine explodes during a safety test, triggering the worst nuclear disaster in history. As lethal radioactive contamination spreads across Europe, Soviet scientist Valery Legasov and state official Boris Shcherbina lead the desperate effort to contain the catastrophe, while the Soviet state apparatus attempts to suppress the truth. A harrowing account of heroism, political corruption, and the devastating cost of institutional lies.', 2019, 65, false, 'https://image.tmdb.org/t/p/w500/hlLXt2tOPT6RRnjiUmoxyG1LTFi.jpg', 'https://www.youtube.com/watch?v=s9APLXM9Ei8', 'https://www.netflix.com/title/81005916', 'series', 1, 5, '[{"season":1,"episodes":5}]'::jsonb),
('The Last of Us', 'Twenty years after a fungal pandemic ravaged civilization, turning infected humans into monstrous creatures, hardened smuggler Joel is hired to escort fourteen-year-old Ellie across the quarantine zones and lawless wilderness of a post-apocalyptic America. Ellie carries a secret that could change the fate of humanity, and as the pair traverse the ruins of a once-great nation, their bond deepens into a father-daughter relationship forged by danger, loss, and the will to survive at any cost.', 2023, 55, false, 'https://image.tmdb.org/t/p/w500/uKvVjHNqB5VmOrdxqAt2F7J78ED.jpg', 'https://www.youtube.com/watch?v=uLtkt8BonwM', 'https://www.netflix.com/title/81435684', 'series', 2, 16, '[{"season":1,"episodes":9},{"season":2,"episodes":7}]'::jsonb),
('Wednesday', 'Wednesday Addams, the sardonic and deadpan eldest child of the Addams family, is enrolled at Nevermore Academy after being expelled from multiple schools. At this Gothic boarding school for outcasts and misfits, Wednesday navigates new friendships, manages her emerging psychic powers, and becomes entangled in a murder mystery connected to her parents'' past. With her razor-sharp wit and unflinching embrace of the macabre, Wednesday must solve the mystery before she becomes the next victim.', 2022, 48, false, 'https://image.tmdb.org/t/p/w500/9PFonBhy4cQy7Jz20NpMygczOkv.jpg', 'https://www.youtube.com/watch?v=Di310WS8zLk', 'https://www.netflix.com/title/81231974', 'series', 1, 8, '[{"season":1,"episodes":8}]'::jsonb),
('Squid Game', 'Seong Gi-hun, a divorced and indebted chauffeur living with his elderly mother, is recruited into a mysterious survival competition along with 455 other desperate individuals, all drowning in financial ruin. The players discover that familiar childhood games have become lethal elimination rounds with a staggering ₩45.6 billion prize — but elimination means death. As alliances form and shatter, the game exposes the darkest extremes of human nature when survival is pitted against morality and greed.', 2021, 54, false, 'https://image.tmdb.org/t/p/w500/dDlEmu3EZ0Pgg93K2SVNLCjCSvE.jpg', 'https://www.youtube.com/watch?v=oqxAJKy0ii4', 'https://www.netflix.com/title/81040344', 'series', 2, 16, '[{"season":1,"episodes":9},{"season":2,"episodes":7}]'::jsonb),
('The Boys', 'In a world where superheroes are real but corrupt — controlled by the mega-corporation Vought International and more concerned with brand deals and ratings than saving lives — a ragtag group of vigilantes known as "The Boys" sets out to expose the truth about the Seven, the premier superhero team. Led by the vengeful Billy Butcher, who has a personal score to settle with the seemingly perfect Homelander, the team navigates a darkly satirical world where absolute power has corrupted absolutely.', 2019, 58, false, 'https://image.tmdb.org/t/p/w500/2zmTngn1tYC1AvfnrFLhxeD82hz.jpg', 'https://www.youtube.com/watch?v=tcrNsIaQkb4', 'https://www.netflix.com/title/81036534', 'series', 4, 32, '[{"season":1,"episodes":8},{"season":2,"episodes":8},{"season":3,"episodes":8},{"season":4,"episodes":8}]'::jsonb),
('Arcane', 'Set in the utopian city of Piltover and the oppressed underground district of Zaun, Arcane follows the divergent paths of two sisters — the idealistic Vi and the volatile Jinx — whose bond is shattered by a conflict that threatens to tear both cities apart. As revolutionary Hextech technology promises progress for Piltover, it becomes a source of dangerous power struggles and personal transformation in Zaun. A visually stunning animated epic about family, ambition, and the cost of progress.', 2021, 42, false, 'https://image.tmdb.org/t/p/w500/fqldf2t8ztc9aiwn3k6mlX3tvRT.jpg', 'https://www.youtube.com/watch?v=fXmAurh012s', 'https://www.netflix.com/title/81435684', 'series', 2, 18, '[{"season":1,"episodes":9},{"season":2,"episodes":9}]'::jsonb),
('Mad Max: Fury Road', 'In a post-apocalyptic wasteland where water and gasoline are the most precious commodities, the rogue warrior Max Rockatansky is captured by the War Boys of the tyrannical Immortan Joe. When Imperator Furiosa leads a daring escape across the desert with Joe''s enslaved wives, Max finds himself swept up in a relentless, high-octane pursuit that becomes a fight for redemption and survival against impossible odds.', 2015, 120, true, NULL, 'https://www.youtube.com/watch?v=hEJnMQG9ev8', 'https://www.netflix.com/title/80025919', 'movie', NULL, NULL, NULL),
('John Wick', 'Legendary retired hitman John Wick is forced back into the criminal underworld he abandoned when a brash Russian gangster''s son steals his prized car and kills his beloved puppy — the last gift from his recently deceased wife. What follows is a meticulously choreographed path of vengeance through New York''s hidden criminal underground, as Wick reminds everyone exactly why he was once feared as the indomitable "Baba Yaga."', 2014, 101, false, NULL, 'https://www.youtube.com/watch?v=C0BMx-qxsP4', 'https://www.netflix.com/title/80013762', 'movie', NULL, NULL, NULL),
('Mission: Impossible - Fallout', 'When a covert mission to recover stolen plutonium goes catastrophically wrong, Ethan Hunt and his IMF team find themselves in a desperate race against time. Shadowed by a CIA assassin and haunted by the consequences of past missions, Hunt must navigate a treacherous web of international espionage, confront impossible choices between duty and loyalty, and execute death-defying stunts across the globe to prevent a nuclear catastrophe.', 2018, 147, false, NULL, 'https://www.youtube.com/watch?v=wb49-oV0F78', 'https://www.netflix.com/title/81004279', 'movie', NULL, NULL, NULL),
('Spider-Man: Into the Spider-Verse', 'Brooklyn teenager Miles Morales stumbles into a multiverse-shattering event when a particle accelerator opens portals to alternate dimensions, bringing together spider-powered heroes from different realities. Mentored by a jaded, older Peter Parker and joined by Spider-Woman, Spider-Man Noir, Peni Parker, and Spider-Ham, Miles must embrace his own powers to stop the Kingpin''s dangerous plan and save all of reality.', 2018, 117, true, NULL, 'https://www.youtube.com/watch?v=g4Hbz2jLxvQ', 'https://www.netflix.com/title/81002747', 'movie', NULL, NULL, NULL),
('The Raid', 'A SWAT team becomes trapped inside a thirty-story apartment building ruled by a ruthless drug lord and his army of killers. As they fight their way up floor by floor through hordes of deadly combatants, rookie officer Rama discovers a dark secret that connects his family to the criminal empire. Featuring breathtaking martial arts choreography that redefined the action genre.', 2011, 101, false, NULL, 'https://www.youtube.com/watch?v=m6Q7KnXpNOg', 'https://www.netflix.com/title/70262342', 'movie', NULL, NULL, NULL),
('12 Years a Slave', 'Based on the true story of Solomon Northup, a free African-American man living with his family in Saratoga, New York, who is kidnapped and sold into slavery in the Deep South in 1841. Over twelve harrowing years, Solomon endures unimaginable brutality under different slaveholders while desperately holding on to his dignity and hope of returning to his family, bearing witness to the systematic inhumanity of the American slave system.', 2013, 134, true, NULL, 'https://www.youtube.com/watch?v=z02Ie8wKKRg', 'https://www.netflix.com/title/70274320', 'movie', NULL, NULL, NULL),
('Moonlight', 'Told across three defining chapters — childhood, adolescence, and adulthood — Moonlight follows Chiron, a young Black man growing up in a rough neighborhood of Miami. Grappling with his identity, sexuality, and the pain of an absent mother addicted to drugs, Chiron finds unexpected tenderness from a drug dealer named Juan and navigates the complexities of human connection in a world that constantly demands he be someone he''s not.', 2016, 111, true, NULL, 'https://www.youtube.com/watch?v=9NJj12tiBzc', 'https://www.netflix.com/title/80121348', 'movie', NULL, NULL, NULL),
('The Pianist', 'Polish-Jewish pianist Władysław Szpilman witnesses the horrifying Nazi occupation of Warsaw — the razing of the ghetto, the deportation of his family to concentration camps, and the systematic destruction of everything he knew. Surviving alone amidst the ruins, Szpilman endures years of hiding, starvation, and terror, sustained only by his music and the occasional act of unexpected compassion, in this devastating true story of resilience during the Holocaust.', 2002, 150, true, NULL, 'https://www.youtube.com/watch?v=BFwGqLa_oAo', 'https://www.netflix.com/title/60025061', 'movie', NULL, NULL, NULL),
('Room', 'Joy "Ma" Newsome has been held captive in a tiny shed for seven years, during which she has raised her five-year-old son Jack, whose entire world is the small space he calls "Room." When they finally engineer a daring escape, both mother and son must confront the overwhelming challenge of reintegrating into a world that has moved on without them — Jack experiencing the vastness of reality for the first time, and Ma facing traumas she had suppressed to survive.', 2015, 118, true, NULL, 'https://www.youtube.com/watch?v=E_Ci-pAL4eE', 'https://www.netflix.com/title/80073950', 'movie', NULL, NULL, NULL),
('The Grand Budapest Hotel', 'In the fictional Republic of Zubrowka between the wars, legendary concierge Gustave H. and his devoted lobby boy Zero Moustafa become embroiled in the theft of a priceless Renaissance painting, a battle over a family fortune, and a rapidly escalating conflict with a fascist paramilitary organization — all set against the backdrop of a fading European civilization. A whimsical, meticulously crafted tale of friendship, loyalty, and the fleeting nature of elegance.', 2014, 99, true, NULL, 'https://www.youtube.com/watch?v=1Fg5iWmQjwk', 'https://www.netflix.com/title/70295915', 'movie', NULL, NULL, NULL),
('Blade Runner 2049', 'Thirty years after the events of the original film, LAPD Officer K, a new-generation replicant, unearths a long-buried secret that has the potential to plunge what remains of society into chaos. K''s discovery leads him on a quest to find former blade runner Rick Deckard, who has been missing for decades, forcing both men to confront fundamental questions about what it means to be human in a world of artificial beings and corporate omnipotence.', 2017, 164, true, NULL, 'https://www.youtube.com/watch?v=gCcx85zbxz4', 'https://www.netflix.com/title/80185086', 'movie', NULL, NULL, NULL),
('Arrival', 'When twelve mysterious alien spacecraft appear at locations across the globe, linguist Dr. Louise Banks is recruited by the U.S. military to lead a team in communicating with the extraterrestrials. As she deciphers their complex, non-linear language, Louise begins experiencing strange visions that challenge her understanding of time itself. A profound exploration of language, memory, and the choices we would make if we could see the future.', 2016, 116, false, NULL, 'https://www.youtube.com/watch?v=tFMo3UJ4B4g', 'https://www.netflix.com/title/80117533', 'movie', NULL, NULL, NULL),
('Ex Machina', 'Young programmer Caleb Smith wins a week-long visit to the secluded mountain estate of Nathan Bateman, the brilliant but reclusive CEO of the world''s largest tech company. There, Caleb discovers he has been chosen to evaluate the human qualities of Ava, an extraordinarily advanced humanoid A.I. As the sessions progress, the boundaries between manipulation and genuine emotion blur, leading to a tense psychological game where nothing is as it appears.', 2014, 108, true, NULL, 'https://www.youtube.com/watch?v=EoQuVnKhxaM', 'https://www.netflix.com/title/80023689', 'movie', NULL, NULL, NULL),
('Dune', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet Arrakis — the only source of the most precious substance in the cosmos — only those who can conquer their fear will survive.', 2021, 155, true, NULL, 'https://www.youtube.com/watch?v=8g18jFHCLXk', 'https://www.netflix.com/title/81340079', 'movie', NULL, NULL, NULL),
('Edge of Tomorrow', 'Major William Cage, an inexperienced military officer, is dropped into what amounts to a suicide mission against invading aliens known as Mimics. Killed within minutes, Cage inexplicably wakes up the previous morning and is forced to relive the same brutal day of combat over and over. Partnered with Special Forces warrior Rita Vrataski, he gradually transforms from a coward into a lethal soldier, using each death as a chance to learn the enemy''s patterns and find a way to victory.', 2014, 113, false, NULL, 'https://www.youtube.com/watch?v=yUmSVcttXnI', 'https://www.netflix.com/title/70303377', 'movie', NULL, NULL, NULL),
('Get Out', 'Chris Washington, a young African-American man, visits the upscale estate of his white girlfriend Rose''s parents for a weekend getaway. Initially attributing the family''s overly accommodating behavior to nervous attempts to deal with their daughter''s interracial relationship, Chris gradually discovers a sinister truth lurking beneath the surface of their liberal facade — a horrifying conspiracy that transforms this social satire into a chilling descent into psychological terror.', 2017, 104, true, NULL, 'https://www.youtube.com/watch?v=DzfpyUB60YY', 'https://www.netflix.com/title/80149508', 'movie', NULL, NULL, NULL),
('Gone Girl', 'On the morning of his fifth wedding anniversary, Nick Dunne reports his wife Amy missing from their Missouri home. Under mounting pressure from the media circus and police investigation, the portrait of a perfect marriage begins to crumble, and Nick''s evasive behavior makes him the prime suspect. But nothing is as it seems in this serpentine thriller that dissects the toxic dynamics of modern marriage, media manipulation, and the dark psychology of deception.', 2014, 149, false, NULL, 'https://www.youtube.com/watch?v=2-_-1nJf8Vg', 'https://www.netflix.com/title/70305893', 'movie', NULL, NULL, NULL),
('Shutter Island', 'In 1954, U.S. Marshal Teddy Daniels and his new partner Chuck Aule arrive at Ashecliffe Hospital, a fortress-like institution for the criminally insane on Shutter Island in Boston Harbor, to investigate the impossible disappearance of a patient. As a massive storm traps them on the island, Teddy''s investigation is met with resistance from the hospital''s enigmatic chief psychiatrist, and he begins to question everything — including his own sanity.', 2010, 138, false, NULL, 'https://www.youtube.com/watch?v=5iaYLCiq5RM', 'https://www.netflix.com/title/70095137', 'movie', NULL, NULL, NULL),
('A Quiet Place', 'In a post-apocalyptic world overrun by blind but hyper-sensitive alien predators that hunt by sound, the Abbott family navigates daily life in enforced silence. Communicating through sign language and walking barefoot, they have survived longer than most — but when an accidental noise alerts the creatures, and with a baby on the way, they must fight for their lives using nothing but ingenuity and complete quiet.', 2018, 90, false, NULL, 'https://www.youtube.com/watch?v=WR7cc5t7tv8', 'https://www.netflix.com/title/80227654', 'movie', NULL, NULL, NULL),
('Hereditary', 'After the death of her secretive and domineering mother, artist Annie Graham and her family begin to unravel cryptic and increasingly terrifying secrets about their ancestry. As the family is drawn deeper into a nightmare of escalating supernatural events, they discover that the darkness they face is not random but inherited — a carefully orchestrated evil passed down through generations that threatens to consume them entirely.', 2018, 127, false, NULL, 'https://www.youtube.com/watch?v=V6wWKNij_1M', 'https://www.netflix.com/title/80199398', 'movie', NULL, NULL, NULL),
('Knives Out', 'When renowned crime novelist Harlan Thrombey is found dead in his estate the morning after his 85th birthday celebration, the eccentric Detective Benoit Blanc is mysteriously enlisted to investigate. As Blanc peels back the layers of deception among Harlan''s dysfunctional family — each member with motive, means, and secrets — a witty and intricate whodunit unfolds that subverts every expectation and delivers a razor-sharp commentary on privilege and morality.', 2019, 130, false, NULL, 'https://www.youtube.com/watch?v=qGqiGp562vs', 'https://www.netflix.com/title/81037684', 'movie', NULL, NULL, NULL),
('The Nice Guys', 'In smog-choked 1977 Los Angeles, down-on-his-luck private eye Holland March and tough enforcer Jackson Healy form an unlikely partnership to investigate the disappearance of a young woman named Amelia. What begins as a routine missing-person case spirals into a sprawling conspiracy involving the auto industry, the Department of Justice, and a Detroit hit squad, all wrapped in the decadent, sun-soaked noir of the ''70s.', 2016, 116, false, NULL, 'https://www.youtube.com/watch?v=GQR5zsLHbYw', 'https://www.netflix.com/title/80079025', 'movie', NULL, NULL, NULL),
('Jojo Rabbit', 'Johannes "Jojo" Betzler is a lonely German boy in the waning days of World War II whose worldview is turned upside down when he discovers his mother Rosie is hiding a Jewish girl named Elsa in their attic. Guided by his imaginary friend — a buffoonish, childlike version of Adolf Hitler — Jojo must confront his blind nationalism and the propaganda he''s been raised on, ultimately learning that love and empathy are more powerful than hate.', 2019, 108, true, NULL, 'https://www.youtube.com/watch?v=tL4McUzXfFI', 'https://www.netflix.com/title/81186753', 'movie', NULL, NULL, NULL),
('The Hangover', 'Two days before his wedding, Doug and his three groomsmen drive to Las Vegas for an epic bachelor party. When they wake up the next morning in a trashed luxury suite with a tiger in the bathroom, a baby in the closet, a missing tooth, and absolutely no memory of the previous night — and no sign of Doug — Phil, Stu, and Alan must retrace their increasingly outrageous steps through Sin City to find the groom before the wedding.', 2009, 100, false, NULL, 'https://www.youtube.com/watch?v=tcdUhdOlz9M', 'https://www.netflix.com/title/70113005', 'movie', NULL, NULL, NULL),
('La La Land', 'In modern-day Los Angeles, aspiring actress Mia Dolan, weary of audition rejections, meets Sebastian Wilder, a jazz pianist clinging to dreams of opening his own club. Their whirlwind romance ignites creative ambitions in both, but as success beckons them in different directions, they must confront the heartbreaking question of whether their love can survive the demands of the dreams they''ve fought so hard to achieve. A bittersweet love letter to the dreamers.', 2016, 128, true, NULL, 'https://www.youtube.com/watch?v=0pdqf4P9MB8', 'https://www.netflix.com/title/80095365', 'movie', NULL, NULL, NULL),
('The Notebook', 'In a nursing home, an elderly man reads from a faded notebook to a woman suffering from dementia, telling the story of Noah Calhoun and Allie Hamilton — a poor country boy and a wealthy city girl whose passionate summer romance in 1940s South Carolina is torn apart by war and class differences. Years later, their paths cross again, forcing Allie to choose between her comfortable life and the all-consuming love she never forgot.', 2004, 123, false, NULL, 'https://www.youtube.com/watch?v=yDJIcYE32NU', 'https://www.netflix.com/title/60036227', 'movie', NULL, NULL, NULL),
('Call Me by Your Name', 'During the languid summer of 1983 in northern Italy, seventeen-year-old Elio Perlman spends his days reading, playing classical music, and swimming — until Oliver, a twenty-four-year-old American scholar, arrives to work as an intern for Elio''s professor father. As the weeks pass, an unspoken attraction between Elio and Oliver evolves into a tender and transformative first love, set against the sun-drenched beauty of the Italian countryside.', 2017, 132, true, NULL, 'https://www.youtube.com/watch?v=Z9AYPxH5NTM', 'https://www.netflix.com/title/80169498', 'movie', NULL, NULL, NULL),
('Crazy Rich Asians', 'New York-born economics professor Rachel Chu accompanies her boyfriend Nick Young to his best friend''s wedding in Singapore, only to discover that Nick is the scion of one of Asia''s wealthiest families. Thrust into a world of opulent excess, jealous socialites, and a formidable future mother-in-law who considers Rachel unworthy, Rachel must prove her worth on her own terms while navigating the complex intersection of love, family, and cultural expectations.', 2018, 120, false, NULL, 'https://www.youtube.com/watch?v=ZQ-YX-5bAs0', 'https://www.netflix.com/title/80230147', 'movie', NULL, NULL, NULL),
('The Shape of Water', 'In a top-secret government laboratory in Cold War-era Baltimore, mute janitor Elisa Esposito discovers a classified experiment — an amphibious humanoid creature captured from the Amazon and held captive for study. An otherworldly connection forms between Elisa and the creature, and with the help of her neighbor and coworker, she devises a daring plan to rescue him before he is destroyed by the military. A luminous fairy tale about finding love in the most unlikely of places.', 2017, 123, true, NULL, 'https://www.youtube.com/watch?v=XFYWazblaUA', 'https://www.netflix.com/title/80185425', 'movie', NULL, NULL, NULL),
('The Departed', 'In South Boston, the Irish mob led by ruthless crime lord Frank Costello plants Colin Sullivan as a mole inside the Massachusetts State Police, while the police assign undercover officer Billy Costigan to infiltrate Costello''s organization. As both moles climb their respective ladders, a deadly cat-and-mouse game unfolds when each side discovers it has a rat — and Sullivan and Costigan race to identify each other before being exposed and eliminated.', 2006, 151, true, NULL, 'https://www.youtube.com/watch?v=iVMFWkVsGBs', 'https://www.netflix.com/title/70044690', 'movie', NULL, NULL, NULL),
('No Country for Old Men', 'While hunting antelope in the sun-scorched West Texas desert, welder Llewelyn Moss stumbles upon the aftermath of a drug deal gone horribly wrong — dead bodies, heroin, and a satchel containing two million dollars in cash. His decision to take the money sets off a relentless chain of violence as he is pursued by the terrifyingly methodical killer Anton Chigurh, whose weapon of choice is a captive bolt pistol and whose philosophy leaves no room for mercy.', 2007, 122, true, NULL, 'https://www.youtube.com/watch?v=38A__WT3-o0', 'https://www.netflix.com/title/70071613', 'movie', NULL, NULL, NULL),
('The Town', 'In Charlestown, Boston — a neighborhood that has produced more bank robbers than anywhere in the world — Doug MacRay leads a crew of ruthless criminals in a series of brazen heists. When they take bank manager Claire Keesey hostage during a robbery, Doug falls for her while trying to determine how much she knows. As the FBI closes in and his volatile partner threatens Claire, Doug faces an impossible choice between his criminal life and the woman who could save him from it.', 2010, 125, false, NULL, 'https://www.youtube.com/watch?v=ega4ZMSyPMI', 'https://www.netflix.com/title/70135109', 'movie', NULL, NULL, NULL),
('Hell or High Water', 'In the drought-stricken plains of West Texas, divorced father Toby Howard and his reckless ex-con brother Tanner execute a series of calculated bank robberies targeting branches of the institution threatening to foreclose on their family ranch. As aging Texas Ranger Marcus Hamilton and his partner methodically close in on the brothers, the film unfolds as a modern Western about economic desperation, brotherly bonds, and the vanishing promise of the American frontier.', 2016, 102, false, NULL, 'https://www.youtube.com/watch?v=JQoqsKoJVDw', 'https://www.netflix.com/title/80100067', 'movie', NULL, NULL, NULL),
('Wind River', 'On the frozen Wind River Indian Reservation in Wyoming, U.S. Fish and Wildlife agent Cory Lambert discovers the body of an eighteen-year-old Native American girl in the snow, barefoot and miles from anywhere. Teamed with inexperienced FBI agent Jane Banner, Lambert uses his tracking skills and deep knowledge of the harsh landscape to unravel the mystery of the young woman''s death, exposing the isolation and injustice faced by Indigenous communities on America''s forgotten reservations.', 2017, 107, false, NULL, 'https://www.youtube.com/watch?v=zHLwYVo_O2U', 'https://www.netflix.com/title/80149646', 'movie', NULL, NULL, NULL),
('Whiplash', 'Nineteen-year-old Andrew Neiman dreams of becoming one of the greatest jazz drummers in history. At the prestigious Shaffer Conservatory, he catches the eye of Terence Fletcher, a legendary instructor renowned for his terrifying teaching methods that push students to the absolute breaking point. What ensues is a ferocious psychological battle between mentor and student that raises profound questions about the cost of greatness, the nature of abuse, and whether artistry justifies suffering.', 2014, 106, true, NULL, 'https://www.youtube.com/watch?v=7d_jQycdQGo', 'https://www.netflix.com/title/70299275', 'movie', NULL, NULL, NULL),
('Baby Driver', 'Baby is a talented young getaway driver who relies on the beat of his personal soundtrack to be the best in the game. Coerced into working for crime boss Doc, Baby meets the girl of his dreams, waitress Debora, and sees a chance at a normal life. But when a heist goes dangerously sideways, Baby is forced into a do-or-die situation to escape the criminal world and save the woman he loves, set to the pulse-pounding rhythm of a meticulously curated playlist.', 2017, 113, false, NULL, 'https://www.youtube.com/watch?v=z2z857RSfhk', 'https://www.netflix.com/title/80142090', 'movie', NULL, NULL, NULL),
('The Social Network', 'In 2003, Harvard sophomore Mark Zuckerberg, fueled by a painful breakup and a restless intellect, creates FaceMash and then launches "The Facebook" from his dorm room. What begins as a college networking site explodes into a global social media revolution worth billions, but the meteoric rise comes at a devastating personal cost — shattering friendships, igniting bitter lawsuits, and raising fundamental questions about innovation, loyalty, and the price of genius.', 2010, 120, true, NULL, 'https://www.youtube.com/watch?v=lB95KLmpLR4', 'https://www.netflix.com/title/70132721', 'movie', NULL, NULL, NULL),
('Django Unchained', 'In 1858 America, two years before the Civil War, German-born bounty hunter Dr. King Schultz frees slave Django and recruits him as his partner. Together they hunt the South''s most wanted criminals, and Schultz agrees to help Django rescue his wife Broomhilda from the charming but monstrously cruel plantation owner Calvin Candie. Their daring plan to infiltrate Candie''s Mississipi estate leads to an explosive confrontation where revenge meets justice in a blaze of gunfire.', 2012, 165, true, NULL, 'https://www.youtube.com/watch?v=0fUCuvNlOCg', 'https://www.netflix.com/title/70230640', 'movie', NULL, NULL, NULL),
('Joker', 'In 1981 Gotham City, failed stand-up comedian Arthur Fleck navigates a society that continuously marginalizes and mistreats him. Suffering from a neurological condition that causes uncontrollable laughter, Arthur spirals into madness as every aspect of his life — his dreams, his relationship with his mother, his connection to reality — collapses around him. His transformation into the anarchic figure known as the Joker sparks a violent revolution among Gotham''s disenfranchised.', 2019, 122, true, NULL, 'https://www.youtube.com/watch?v=zAGVQLHvwOY', 'https://www.netflix.com/title/81116004', 'movie', NULL, NULL, NULL),
('True Detective', 'Seasonal anthology series in which police investigations unearth the personal and professional secrets of those involved, both within and outside the law.', 2014, 55, false, NULL, NULL, NULL, 'movie', NULL, NULL, NULL),
('Succession', 'The Roy family is known for controlling the biggest media and entertainment company in the world. However, their world changes when their father steps down from the company.', 2018, 60, false, NULL, NULL, NULL, 'movie', NULL, NULL, NULL),
('The Bear', 'A young chef from the fine dining world comes home to Chicago to run his family sandwich shop.', 2022, 30, false, NULL, NULL, NULL, 'movie', NULL, NULL, NULL);
