INSERT INTO reviews (movie_id, user_id, rating, review_text) VALUES
((SELECT movie_id FROM movies WHERE title = 'The Godfather' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.8, 'A masterclass in storytelling. Brando and Pacino deliver performances that define cinema. The pacing, the music, the dialogue — everything is pitch-perfect. This is not just a movie about the mafia; it is a profound exploration of family, loyalty, and the corrupting nature of power.'),
((SELECT movie_id FROM movies WHERE title = 'The Godfather' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 9.5, 'Coppola crafted something timeless. The way the film builds tension through quiet moments rather than explosions is brilliant. The baptism scene intercut with the assassinations remains one of cinema''s greatest sequences.'),
((SELECT movie_id FROM movies WHERE title = 'The Godfather' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 10.0, 'I''ve watched this film over 20 times and discover something new each viewing. The cinematography by Gordon Willis — "The Prince of Darkness" — creates an atmosphere that pulls you into this world completely. An offer you truly cannot refuse.'),
((SELECT movie_id FROM movies WHERE title = 'The Godfather' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 9.0, 'The transformation of Michael Corleone from war hero to ruthless don is one of the most compelling character arcs ever filmed. The dinner scene in the Italian restaurant is acting at its finest.'),
((SELECT movie_id FROM movies WHERE title = 'The Dark Knight' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.5, 'Heath Ledger''s Joker is the greatest villain performance in cinema history. Every scene he''s in crackles with menacing energy. Nolan elevated the superhero genre into high art with this film.'),
((SELECT movie_id FROM movies WHERE title = 'The Dark Knight' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 9.0, 'More than a superhero movie — it''s a gripping crime thriller that happens to feature a man in a bat suit. The moral dilemmas, the Harvey Dent arc, the practical effects. Everything works.'),
((SELECT movie_id FROM movies WHERE title = 'The Dark Knight' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ScreenSavant'), 9.7, 'The interrogation scene between Batman and Joker is cinema perfection. Two opposing forces colliding with incredible dialogue and performances. Hans Zimmer''s score elevates every single moment.'),
((SELECT movie_id FROM movies WHERE title = 'Parasite' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 9.5, 'Bong Joon-ho masterfully blends dark comedy, thriller, and social commentary into a seamless narrative. The way the film shifts tone — from funny to deeply unsettling — without ever feeling jarring is extraordinary filmmaking.'),
((SELECT movie_id FROM movies WHERE title = 'Parasite' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 9.8, 'A scathing critique of wealth inequality wrapped in a genre-bending thriller. Every frame is meticulously composed. The "smell" motif is subtle genius. Deserved every single Oscar it won.'),
((SELECT movie_id FROM movies WHERE title = 'Parasite' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 9.0, 'The less you know going in, the better. This film takes turns you genuinely cannot predict. The contrast between the Park family''s modernist home and the Kim family''s semi-basement tells the entire story in architecture.'),
((SELECT movie_id FROM movies WHERE title = 'Inception' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.0, 'Nolan built a puzzle-box blockbuster that respects the audience''s intelligence. The rotating hallway fight is jaw-dropping, and the emotional core — Cobb''s guilt over Mal — gives the spectacle real weight.'),
((SELECT movie_id FROM movies WHERE title = 'Inception' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ScreenSavant'), 8.5, 'A mind-bending heist film that layers dreams within dreams without losing coherence. The ensemble cast is fantastic. Hans Zimmer''s "Time" might be the most emotionally devastating piece of film music ever composed.'),
((SELECT movie_id FROM movies WHERE title = 'Inception' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'TheFrameJunkie'), 9.2, 'The ending — that spinning top — sparked more debate than any other film moment this century. Whether it falls or not doesn''t matter; what matters is that Cobb walks away. Brilliant storytelling.'),
((SELECT movie_id FROM movies WHERE title = 'The Shawshank Redemption' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 10.0, 'Hope is a dangerous thing, and this film makes you feel every ounce of it. Tim Robbins and Morgan Freeman have possibly the greatest on-screen friendship in movie history. The final act is pure catharsis.'),
((SELECT movie_id FROM movies WHERE title = 'The Shawshank Redemption' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 9.8, 'A film that flopped at the box office but found eternal life through word of mouth. The storytelling is patient, warm, and rewards you for every minute invested. The rooftop beer scene is sublime.'),
((SELECT movie_id FROM movies WHERE title = 'The Shawshank Redemption' AND content_type = 'movie' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 9.5, 'Frank Darabont adapted Stephen King''s novella into something transcendent. The narration by Morgan Freeman is iconic. It''s a film about maintaining your humanity in inhuman conditions.'),
((SELECT movie_id FROM movies WHERE title = 'Breaking Bad' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 10.0, 'The greatest television series ever made. Walter White''s transformation from mild-mannered teacher to Heisenberg is the most compelling character arc in TV history. Bryan Cranston delivers the performance of a lifetime — every season, every episode.'),
((SELECT movie_id FROM movies WHERE title = 'Breaking Bad' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 9.8, 'Vince Gilligan crafted a perfect five-season story with an ending that actually delivers. The tension in "Ozymandias" is almost unbearable. Aaron Paul''s Jesse Pinkman provides the emotional heart that keeps you invested through the darkness.'),
((SELECT movie_id FROM movies WHERE title = 'Breaking Bad' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 9.5, 'What starts as a darkly comic premise becomes a Shakespearean tragedy. The cinematography of the New Mexico desert is stunning. Every character — Hank, Skyler, Mike, Gus — is fully realized. The train heist episode is the most tense hour of TV ever produced.'),
((SELECT movie_id FROM movies WHERE title = 'Breaking Bad' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 9.7, 'This show respects its audience more than any other. The foreshadowing, the symbolism (the fly, the pink teddy bear), the callbacks — everything is intentional. Gus Fring walking out of the exploded room is the most shocking moment in television.'),
((SELECT movie_id FROM movies WHERE title = 'Game of Thrones' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 8.5, 'Seasons 1-4 are some of the greatest television ever produced. The Red Wedding, Tyrion''s trial, the Battle of the Blackwater — unforgettable moments. The later seasons stumbled, but the first four years set a standard for prestige TV that hasn''t been matched.'),
((SELECT movie_id FROM movies WHERE title = 'Game of Thrones' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 8.0, 'An epic fantasy saga that proved the genre could dominate mainstream television. Peter Dinklage''s Tyrion is the heart and soul of the show. The production values, the music by Ramin Djawadi, the scale of it all — nothing else comes close.'),
((SELECT movie_id FROM movies WHERE title = 'Game of Thrones' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'BingeWatcher101'), 7.5, 'The early seasons where the show faithfully adapted George R.R. Martin''s novels are masterful television — complex, shocking, and deeply human. The quality dip in later seasons is disappointing, but the cultural impact is undeniable. Hardhome is peak TV.'),
((SELECT movie_id FROM movies WHERE title = 'Stranger Things' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 8.8, 'A love letter to 80s Spielberg and Stephen King that manages to feel fresh and original. The kids'' performances are remarkable — Millie Bobby Brown as Eleven is a revelation. Season 1 is nearly perfect television. The synth score by Kyle Dixon & Michael Stein is incredible.'),
((SELECT movie_id FROM movies WHERE title = 'Stranger Things' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ScreenSavant'), 8.5, 'Captures the magic of childhood adventure while delivering genuine horror. The Upside Down is one of the most fully realized alternate dimensions in modern sci-fi. Season 4''s Vecna arc brought the show back to its terrifying roots.'),
((SELECT movie_id FROM movies WHERE title = 'Stranger Things' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'BingeWatcher101'), 8.0, 'The Duffer Brothers nailed the nostalgia factor without making it feel cheap. The ensemble cast grows with the show beautifully. "Running Up That Hill" becoming a cultural phenomenon again through this show proves its power.'),
((SELECT movie_id FROM movies WHERE title = 'The Witcher' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 7.5, 'Henry Cavill''s dedication to Geralt is admirable — he clearly loves the source material. The fight choreography is excellent, particularly the Blaviken battle. The non-linear timeline in Season 1 is initially confusing but rewarding on rewatch.'),
((SELECT movie_id FROM movies WHERE title = 'The Witcher' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'BingeWatcher101'), 7.0, 'A solid fantasy series carried largely by Cavill''s charisma and some impressive action sequences. The world-building improves each season. Joey Batey''s Jaskier steals every scene he''s in. "Toss a Coin to Your Witcher" is an earworm.'),
((SELECT movie_id FROM movies WHERE title = 'Money Heist' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 8.5, 'The Professor''s master plan unfolds with addictive precision. This Spanish thriller proves that great storytelling transcends language barriers. Tokyo''s narration adds urgency, and the ensemble cast makes you root for criminals. Bella Ciao never sounded so revolutionary.'),
((SELECT movie_id FROM movies WHERE title = 'Money Heist' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 8.0, 'A heist series that keeps raising the stakes without jumping the shark (mostly). The character dynamics inside the Mint are fascinating — watching strangers become family under pressure. Berlin is one of the most complex antiheroes in recent TV.'),
((SELECT movie_id FROM movies WHERE title = 'Dark' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.5, 'The most intricately plotted show ever made. The way Dark weaves together multiple timelines, paradoxes, and family connections is staggering. Every detail matters. You need a family tree chart to follow it, and that''s a compliment. German sci-fi at its absolute finest.'),
((SELECT movie_id FROM movies WHERE title = 'Dark' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'TheFrameJunkie'), 9.2, 'Makes most time travel stories look like children''s books. The show''s commitment to its own internal logic is unmatched. Ben Frost''s haunting score and the perpetually overcast aesthetic create an atmosphere of beautiful dread. The final season ties everything together masterfully.'),
((SELECT movie_id FROM movies WHERE title = 'The Crown' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 8.5, 'Peter Morgan transforms royal history into compelling human drama. Claire Foy''s Elizabeth II and Olivia Colman''s evolution of the character are both extraordinary. The production design is impeccable — every palace, every costume feels authentic.'),
((SELECT movie_id FROM movies WHERE title = 'The Crown' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 8.0, 'A fascinating exploration of duty versus personal desire. The show''s strength is making you empathize with one of the most privileged families on Earth. The Diana seasons are heartbreaking. Imelda Staunton''s final portrayal brings regal dignity to the role.'),
((SELECT movie_id FROM movies WHERE title = 'Peaky Blinders' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 8.8, 'Cillian Murphy''s Tommy Shelby is one of TV''s greatest antiheroes — calculating, haunted, magnetic. The anachronistic soundtrack choices (Nick Cave, Arctic Monkeys over 1920s Birmingham) shouldn''t work but absolutely do. Style and substance in equal measure.'),
((SELECT movie_id FROM movies WHERE title = 'Peaky Blinders' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ScreenSavant'), 8.5, 'A crime saga that gets more ambitious with each season. Tom Hardy''s Alfie Solomons is a scene-stealing force of nature. The slow-motion walks set to rock music became iconic for a reason — pure television swagger.'),
((SELECT movie_id FROM movies WHERE title = 'The Mandalorian' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 8.5, 'Jon Favreau recaptured the spirit of the original Star Wars trilogy — simple storytelling with heart. Pedro Pascal gives a full performance behind a helmet. Baby Yoda (Grogu) is the most adorable character in the franchise. "This is the way" became an instant catchphrase.'),
((SELECT movie_id FROM movies WHERE title = 'The Mandalorian' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'BingeWatcher101'), 8.0, 'A space western that proves Star Wars works best on a personal scale. The episodic format allows for creative guest directors to put their stamp on each chapter. The practical effects and sets through StageCraft technology look incredible.'),
((SELECT movie_id FROM movies WHERE title = 'Chernobyl' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.8, 'The most terrifying miniseries ever made — because it actually happened. The first episode, depicting the immediate aftermath of the explosion, is almost unwatchable in its horror. Jared Harris and Stellan Skarsgård deliver career-defining performances. Essential viewing.'),
((SELECT movie_id FROM movies WHERE title = 'Chernobyl' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 9.5, 'Craig Mazin transformed a nuclear disaster into a meditation on truth, sacrifice, and institutional corruption. The bridge scene where citizens watch the reactor burn — unknowingly receiving lethal radiation — is haunting. The sound design is suffocatingly oppressive.'),
((SELECT movie_id FROM movies WHERE title = 'Chernobyl' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'TheFrameJunkie'), 9.7, 'Five episodes of pure, unrelenting brilliance. The show''s thesis — "What is the cost of lies?" — resonates far beyond 1986 Soviet Union. The liquidators'' rooftop cleanup scene is the most stressful 10 minutes of television I have ever watched.'),
((SELECT movie_id FROM movies WHERE title = 'The Last of Us' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'FilmFanatic92'), 9.0, 'The gold standard for video game adaptations. Pedro Pascal and Bella Ramsey have incredible chemistry as Joel and Ellie. Episode 3 — "Long, Long Time" with Nick Offerman and Murray Bartlett — is a standalone masterpiece that made the entire world cry.'),
((SELECT movie_id FROM movies WHERE title = 'The Last of Us' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ScreenSavant'), 9.2, 'Craig Mazin proves Chernobyl was no fluke. The show respects the source material while making bold creative choices. The infected are genuinely terrifying, and the practical makeup effects are outstanding. The cold open with the 1968 talk show is a brilliant way to set the tone.'),
((SELECT movie_id FROM movies WHERE title = 'The Last of Us' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 8.8, 'This show understands that the monsters aren''t the point — the human connections are. Joel''s PTSD, Ellie''s survivor guilt, the communities they encounter — every interaction feels earned. The Kansas City arc is thrilling television.'),
((SELECT movie_id FROM movies WHERE title = 'Wednesday' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 7.8, 'Jenna Ortega IS Wednesday Addams. Her deadpan delivery and physicality are perfect. Tim Burton''s gothic aesthetic gives Nevermore Academy real personality. The dance scene went viral for good reason — it''s magnetic. A fun YA mystery with genuine style.'),
((SELECT movie_id FROM movies WHERE title = 'Wednesday' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'BingeWatcher101'), 7.5, 'A charming series that works thanks to Ortega''s commitment to the role. The mystery plotline is serviceable, but the character interactions are where it shines. Thing (the sentient hand) is surprisingly one of the most expressive characters on the show.'),
((SELECT movie_id FROM movies WHERE title = 'Squid Game' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.0, 'Hwang Dong-hyuk created a global phenomenon — childhood games turned into life-or-death competitions is horrifyingly brilliant. The "Red Light, Green Light" sequence is immediately iconic. Beneath the violence is a sharp critique of capitalism that resonates worldwide.'),
((SELECT movie_id FROM movies WHERE title = 'Squid Game' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 8.8, 'K-drama meets Battle Royale with a social conscience. The ensemble cast brings real humanity to characters who could easily be archetypes. Player 001''s twist is genuinely shocking. The set designs — those pastel-colored stairways — are nightmarishly beautiful.'),
((SELECT movie_id FROM movies WHERE title = 'Squid Game' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ScreenSavant'), 8.5, 'The marbles episode destroyed me emotionally. What makes Squid Game special is that it makes you feel for people you just met. The VIPs arc is the weakest element, but the core game sequences are masterfully tense. The glass bridge episode is pure anxiety.'),
((SELECT movie_id FROM movies WHERE title = 'The Boys' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'PopcornPundit'), 8.8, 'The superhero deconstruction we needed. Homelander is the most terrifying villain on TV — Antony Starr plays him with laser-eyed menace and fragile narcissism. The show is viciously funny, shockingly violent, and surprisingly politically sharp.'),
((SELECT movie_id FROM movies WHERE title = 'The Boys' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'TheFrameJunkie'), 8.5, 'Karl Urban''s Butcher provides the perfect counterweight to Homelander''s god complex. The show pulls no punches — literally. The satire of corporate America using superheroes as a vehicle for critique is genius. "Herogasm" is the most unhinged episode of TV ever made.'),
((SELECT movie_id FROM movies WHERE title = 'The Boys' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'BingeWatcher101'), 9.0, 'What if Superman was evil and Amazon owned him? That''s the pitch, and the execution is brilliant. Each season escalates the stakes while deepening the characters. Starlight''s arc from naive hero to genuine rebel is beautifully written.'),
((SELECT movie_id FROM movies WHERE title = 'Arcane' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'CinematicCritic'), 9.5, 'The best animated series since Avatar: The Last Airbender. Fortiche''s animation style — blending 3D characters with 2D painted backgrounds — is breathtaking. Vi and Jinx''s relationship is emotionally devastating. You don''t need to know League of Legends to be blown away.'),
((SELECT movie_id FROM movies WHERE title = 'Arcane' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'ReelTalkReviews'), 9.2, 'Riot Games had no business making something this good. Every frame could be a painting. The voice acting is superb — Ella Purnell''s Jinx is heartbreakingly unhinged. The soundtrack (Imagine Dragons, Sting) is perfectly integrated. Animation as high art.'),
((SELECT movie_id FROM movies WHERE title = 'Arcane' AND content_type = 'series' LIMIT 1), (SELECT user_id FROM users WHERE username = 'MovieMaven'), 9.0, 'Arcane proves that video game adaptations can be prestige television. The class struggle between Piltover and Zaun drives a narrative full of complex characters with no easy heroes or villains. Silco is a surprisingly sympathetic antagonist. The fight choreography is stunning.')
